def doc(title,body):
    css='''@page{size:A4;margin:18mm 18mm 19mm;@bottom-right{content:"HOMS draft • Page " counter(page);font:9pt Arial;color:#666}}body{font:10.5pt/1.45 Arial,sans-serif;color:#202b31}h1{font-size:23pt;color:#173d46;border-bottom:3px solid #b89552;padding-bottom:7px}h2{font-size:15pt;color:#173d46;margin-top:24px}h3{font-size:12pt;color:#805f22}.cover{padding-top:60px;min-height:850px}.meta{padding:12px;background:#eef3f1;border-left:4px solid #b89552}.case{padding:14px;background:#f5f6f4;border:1px solid #d5dbd7}.marks{float:right;color:#805f22;font-weight:bold}.warn{font-size:9pt;color:#50585b}.q{break-inside:avoid;margin:12px 0}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbc4c0;padding:7px;vertical-align:top}th{background:#173d46;color:white}li{margin:4px 0}'''
    return f'<!doctype html><html><head><meta charset="utf-8"><title>{html.escape(title)}</title><style>{css}</style></head><body>{body}</body></html>'

def render(kind,n,content):
    dest=OUT/f'PAPER_{n}_{kind}.html'; dest.write_text(doc(f'Grade 12 Business Studies Paper {n} {kind}',content),encoding='utf-8')
    (OUT/f'PAPER_{n}_{kind}.pdf').unlink(missing_ok=True)
    subprocess.run(['libreoffice','-env:UserInstallation=file:///tmp/lo-homs-g12','--headless','--convert-to','pdf','--outdir',str(OUT),str(dest)],check=True,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
    return dest,OUT/f'PAPER_{n}_{kind}.pdf'

for n,p in PAPERS.items():
    if n==1: main_topics=['Business Environments','Business Operations']
    else: main_topics=['Business Ventures','Business Roles']
    front=f'''<section class="cover"><p>HOMS EXAM STUDIO · EDUCATOR REVIEW DRAFT</p><h1>Grade 12 Business Studies<br>Paper {n}</h1><p class="meta"><b>{p['topics']}</b><br>150 marks · 2 hours · Randomized subject seed 20261101<br>Answer Section A, any TWO questions in Section B, and any ONE question in Section C.</p><p class="warn">Original draft assessment for educator moderation. Not an official DBE examination and not authorized for classroom release. Verify current school assessment requirements before use.</p><h2>Instructions</h2><ol><li>Write your name and class on every answer sheet.</li><li>Answer all of Section A.</li><li>In Section B, answer any TWO questions. Each question is 40 marks; only the first two answers will be marked.</li><li>In Section C, answer any ONE essay question.</li><li>Number answers exactly as in the paper. Show calculations where relevant.</li></ol><p><b>Contents:</b> Section A 30 marks; Section B 80 marks counted; Section C 40 marks. Total 150.</p></section>'''
    body=front+'<h2>SECTION A · COMPULSORY (30 marks)</h2><p>Choose the best answer. Each item is worth 2 marks.</p><ol>'
    for i,row in enumerate(MCQ,1):
        body+=f'<li class="q">{html.escape(row[0])}<ol type="A">'+''.join(f'<li>{html.escape(x)}</li>' for x in row[1:5])+'</ol></li>'
    body+='</ol><h2>SECTION B · ANSWER ANY TWO (80 marks counted)</h2><p>Each question is worth 40 marks. Use relevant business terminology and apply your answers to the information provided.</p>'
    for title,qs in p['qs']:
        body+=f'<h3>{html.escape(title)}</h3>'
        if title.startswith('Question 1'): body+=f'<div class="case"><b>Read the case study and answer all parts.</b><br>{html.escape(p["case"])}</div>'
        for qid,prompt,marks in qs: body+=f'<p class="q"><b>{qid}</b> {html.escape(prompt)} <span class="marks">[{marks}]</span></p>'
    body+='<h2>SECTION C · ANSWER ANY ONE (40 marks)</h2><p>Write a structured essay with an introduction, developed discussion, application or examples, and conclusion. Each essay is assessed against the same rubric: introduction and framing (4); accurate knowledge and explanation (12); analysis and application to the stated topic (12); evaluation, justified recommendation or synthesis (8); coherent conclusion and structure (4).</p>'
    for i,(topic,verb) in enumerate([(main_topics[0],'Analyse and evaluate'),(main_topics[1],'Discuss and recommend')],1):
        body+=f'<h3>Essay option {i} · {topic} (40 marks)</h3><p>{verb} how a South African business can respond effectively to current challenges in {topic.lower()}. Develop a balanced argument, use relevant examples and finish with a justified conclusion.</p>'
    body+='<p class="warn">End of Paper '+str(n)+'. Check that you have answered the required number of questions.</p>'
    exam_html,exam_pdf=render('EXAM',n,body)
    memo='<section class="cover"><p>HOMS EXAM STUDIO · CONFIDENTIAL DRAFT MEMORANDUM</p><h1>Grade 12 Business Studies<br>Paper '+str(n)+' Marking Guideline</h1><p class="meta">150 marks available · Award only the marks shown. Accept other relevant, correctly explained answers. Avoid double-credit for repeated points.</p><p class="warn">Draft memo requires educator moderation and subject-specialist review before use.</p></section><h2>SECTION A · ANSWER KEY (30 marks)</h2><table><tr><th>Item</th><th>Answer</th><th>Reason</th></tr>'
    for i,row in enumerate(MCQ,1): memo+=f'<tr><td>{i}</td><td>{row[5]} · {row[row[5].__getitem__(0).isalpha() and "ABCD".index(row[5]) + 1 or 1]}</td><td>One correct option; 2 marks.</td></tr>'
    memo+='</table><h2>SECTION B · MARKING GUIDELINES (80 counted)</h2><p>Each question totals 40. Mark all three questions if attempted; retain the best two complete question scores, subject to school policy.</p>'
    for title,qs in p['qs']:
        memo+=f'<h3>{html.escape(title)}</h3><table><tr><th>Part</th><th>Expected evidence and allocation</th><th>Marks</th></tr>'
        for qid,prompt,marks in qs:
            per=marks
            points=[]
            if marks<=4: points=[GUIDANCE[n].get(qid, f'{per} distinct relevant points, one mark each; accept accurate alternatives.')]
            elif marks<=8: points=[GUIDANCE[n].get(qid, f'{marks//2} relevant points (1 each) with linked explanation/application (1 each).')]
            else: points=[GUIDANCE[n].get(qid, f'{marks//2} relevant developed points (1 knowledge/relevance + 1 explanation/application each).')]
            memo+=f'<tr><td>{qid}</td><td>{html.escape(" ".join(points))} Credit precise use of case evidence where requested; do not award unsupported assertions.</td><td>{marks}</td></tr>'
        memo+='</table>'
    memo+='<h2>SECTION C · ESSAY GUIDELINE (40 marks)</h2><p>Use the common rubric printed on the question paper: framing 4; accurate knowledge 12; analysis/application 12; evaluation/synthesis 8; structure and conclusion 4. Award proportionately for relevant, developed content; accept different defensible positions. A list without explanation cannot receive analysis or evaluation marks.</p><h2>CAPS alignment and moderation note</h2><p>Paper '+str(n)+' addresses the Grade 12 topic pair: '+html.escape(p['topics'])+'. The arrangement follows the DBE Business Studies examination guideline structure (Section A 30; Section B select two of three 40-mark questions; Section C select one of two 40-mark essays; 150 marks, 120 minutes). This is a newly authored practice draft; it is not an official DBE paper. CAPS source SHA-256: e6f0a21b96fa87ccfccb732a9240a579bf0157916b86a1cdd98a2876cf76db27. Before classroom use, an educator must validate topic coverage, the item-level mark scheme, accessibility and current examination policy.</p>'
    memo_html,memo_pdf=render('MEMO',n,memo)

index={'schema':'dio.homs.grade12.full_nsc_candidate.v1','grade':12,'subject':'Business Studies','random_seed':20261101,'papers':[{'paper':n,'topics':p['topics'],'marks':150,'duration_minutes':120} for n,p in PAPERS.items()],'source':{'title':'CAPS Business Studies Grades 10–12','url':'https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558','sha256':'e6f0a21b96fa87ccfccb732a9240a579bf0157916b86a1cdd98a2876cf76db27'},'exam_guideline_url':'https://www.education.gov.za/LinkClick.aspx?fileticket=xNNzxwX_fBs%3D&forcedownload=true&mid=8872&portalid=0&tabid=2512','status':'DRAFT_REQUIRES_EDUCATOR_MODERATION','release_authorized':False}
